1	/// Decides whether a YAML scalar value looks like prose worth
2	/// grammar-checking, as opposed to structural config data
3	/// (identifiers, enum values, URLs, paths, version strings).
4	///
5	/// Comments are never passed through this function — they're
6	/// always linted, handled separately in `YamlMasker`.
7	pub(crate) fn is_prose_scalar(text: &str) -> bool {
8	    let word_count = text.split_whitespace().count();
9	
10	    word_count >= 3 && !looks_url_path_or_version(text) && !looks_like_identifier(text)
11	}
12	
13	fn looks_url_path_or_version(text: &str) -> bool {
14	    for word in text.split_whitespace() {
15	        if word.starts_with("http://") || word.starts_with("https://") || word.starts_with("ftp://")
16	        {
17	            return true;
18	        }
19	
20	        if word.contains('/') || word.contains('\\') {
21	            return true;
22	        }
23	
24	        if is_semver_like(word) {
25	            return true;
26	        }
27	    }
28	
29	    false
30	}
31	
32	/// Matches strings shaped like `1.2.3` or `12.34.56.7` (semver-ish):
33	/// digit groups separated by dots, at least two dots, no other
34	/// characters.
35	fn is_semver_like(word: &str) -> bool {
36	    let trimmed = word.trim_matches(|c: char| !c.is_ascii_alphanumeric());
37	    let parts: Vec<&str> = trimmed.split('.').collect();
38	
39	    parts.len() >= 3
40	        && parts
41	            .iter()
42	            .all(|p| !p.is_empty() && p.chars().all(|c| c.is_ascii_digit()))
43	}
44	
45	/// True if the whole value reads as an identifier/enum/constant
46	/// rather than a sentence: entirely uppercase, or snake_case, or
47	/// kebab-case.
48	fn looks_like_identifier(text: &str) -> bool {
49	    let has_letters = text.chars().any(|c| c.is_alphabetic());
50	
51	    if !has_letters {
52	        return false;
53	    }
54	
55	    let is_all_caps = text.chars().any(|c| c.is_alphabetic())
56	        && text
