fn looks_url_path_or_version(text: &str) -> bool {
    for word in text.split_whitespace() {
        if word.starts_with("http://") || word.starts_with("https://") || word.starts_with("ftp://")
        {
            return true;
        }

        if word.contains('/') || word.contains('\\') {
            return true;
        }

        if is_semver_like(word) {
            return true;
        }
    }

    false
}

/// Matches strings shaped like `1.2.3` or `12.34.56.7` (semver-ish):
/// digit groups separated by dots, at least two dots, no other
/// characters.
fn is_semver_like(word: &str) -> bool {
    let trimmed = word.trim_matches(|c: char| !c.is_ascii_alphanumeric());
    let parts: Vec<&str> = trimmed.split('.').collect();

    parts.len() >= 3
        && parts
            .iter()
            .all(|p| !p.is_empty() && p.chars().all(|c| c.is_ascii_digit()))
}

