50	    fn create_mask(&self, source: &[char]) -> Mask {
51	        self.inner
52	            .create_mask(source)
53	            .iter_allowed(source)
54	            .filter_map(|(span, chars)| {
55	                let mut span = span;
56	                let mut text: String = chars.iter().collect();
57	
58	                // A real shebang only applies to the first line of the file.
59	                // If tree-sitter merged the shebang with following comments,
60	                // keep linting the remainder of the comment block.
61	                if span.start == 0 && text.starts_with("#!") {
62	                    span = trim_leading_shebang(span, chars)?;
63	                    text = span.get_content(source).iter().collect();
64	                }
65	
66	                if (self.ignore_condition)(&text) {
67	                    None
68	                } else {
69	                    Some(span)
70	                }
71	            })
72	            .collect()
73	    }
74	}
