76	fn trim_leading_shebang(span: Span<char>, chars: &[char]) -> Option<Span<char>> {
77	    let first_line_end = chars
78	        .iter()
79	        .position(|c| *c == '\n')
80	        .map_or(chars.len(), |index| index + 1);
81	
82	    let next_content = chars[first_line_end..]
83	        .iter()
84	        .position(|c| !c.is_whitespace())?;
85	
86	    Some(Span::new(
87	        span.start + first_line_end + next_content,
88	        span.end,
89	    ))
90	}
