111	    fn is_scalar_node(n: &tree_sitter::Node) -> bool {
112	        let is_candidate_kind = matches!(
113	            n.kind(),
114	            "plain_scalar" | "single_quote_scalar" | "double_quote_scalar" | "block_scalar"
115	        );
116	
117	        is_candidate_kind && !Self::is_mapping_key(n)
118	    }
