120	    /// True if `n` sits in the "key" slot of its nearest enclosing
121	    /// `block_mapping_pair`/`flow_pair` ancestor -- i.e. its start position
122	    /// coincides with the pair's start position (the key is always the
123	    /// first token in a mapping pair; the value always starts later, after
124	    /// `key:`).
125	    fn is_mapping_key(n: &tree_sitter::Node) -> bool {
126	        let n_start = n.start_byte();
127	        let mut node = *n;
128	
129	        while let Some(parent) = node.parent() {
130	            if matches!(parent.kind(), "block_mapping_pair" | "flow_pair") {
131	                return parent.start_byte() == n_start;
132	            }
133	            node = parent;
134	        }
135	
136	        false
137	    }
138	}
