27	impl YamlMasker {
28	    fn new(language: tree_sitter::Language) -> Self {
29	        Self { language }
30	    }
31	
32	    fn is_comment_node(n: &Node) -> bool {
33	        n.kind() == "comment"
34	    }
35	
36	    fn is_scalar_node(n: &Node) -> bool {
37	        let is_candidate_kind = matches!(
38	            n.kind(),
39	            "plain_scalar" | "single_quote_scalar" | "double_quote_scalar" | "block_scalar"
40	        );
41	
42	        is_candidate_kind && !Self::is_mapping_key(n)
43	    }
44	
45	    /// True if `n` sits in the "key" slot of its nearest enclosing
46	    /// `block_mapping_pair`/`flow_pair` ancestor -- i.e. its start position
47	    /// coincides with the pair's start position (the key is always the
48	    /// first token in a mapping pair; the value always starts later, after
49	    /// `key:`).
50	    fn is_mapping_key(n: &Node) -> bool {
51	        let n_start = n.start_byte();
52	        let mut node = *n;
53	
54	        while let Some(parent) = node.parent() {
55	            if matches!(parent.kind(), "block_mapping_pair" | "flow_pair") {
56	                return parent.start_byte() == n_start;
57	            }
58	            node = parent;
59	        }
60	
61	        false
62	    }
63	}
